    'data-structures': [
        { q: '栈（Stack）的特点是', opts: ['先进先出 FIFO', '后进先出 LIFO', '随机访问', '按优先级出'], ans: 1, tip: '栈 LIFO（Last In First Out）：函数调用栈、撤销 Ctrl+Z、表达式求值、DFS。队列才是 FIFO。' },
        { q: '队列（Queue）的典型应用是', opts: ['函数递归调用', 'DFS 深度优先', 'BFS 广度优先 / 任务调度', '括号匹配'], ans: 2, tip: '队列 FIFO：BFS、操作系统进程调度、消息队列、生产者消费者。函数调用/DFS/括号匹配用栈。' },
        { q: '二叉搜索树（BST）的中序遍历得到的序列是', opts: ['完全随机', '递增有序序列', '递减有序', '层序'], ans: 1, tip: 'BST 性质：左 < 根 < 右；中序（左→根→右）正好按升序访问所有节点。这就是树排序 O(n log n)。' },
        { q: 'BST 平均查找/插入/删除的时间复杂度是', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n log n)'], ans: 1, tip: '平衡 BST 高度 ≈ log n，操作 O(log n)。最坏退化为链表 O(n)（按顺序插入）。AVL/红黑树通过自旋保证平衡。' },
        { q: '堆（Heap）的两个核心性质是', opts: ['完全二叉树 + 堆序性（父≥子或父≤子）', '满二叉树 + 平衡', 'BST + 平衡', '链表 + 排序'], ans: 0, tip: '堆是完全二叉树（数组存储）+ 堆序（大顶堆父≥子，小顶堆父≤子）。优先队列、堆排序 O(n log n)、Top-K 问题都用堆。' },
    ],
    'recursion-vis': [
        { q: '递归算法必须包含的三要素中，不可省略的是', opts: ['循环结构', '基线条件（终止条件）', '全局变量', 'try-catch'], ans: 1, tip: '递归三要素：(1)基线条件（停止递归避免无限调用）；(2)递归调用；(3)子问题规模缩小。缺少基线 → 栈溢出。' },
        { q: 'Fibonacci 朴素递归 fib(n) 的时间复杂度是', opts: ['O(n)', 'O(n log n)', 'O(2ⁿ)', 'O(n²)'], ans: 2, tip: 'fib(n)=fib(n-1)+fib(n-2)，调用树指数膨胀，时间 O(φⁿ)≈O(1.618ⁿ) ≈ O(2ⁿ)。用记忆化或 DP 可降为 O(n)。' },
        { q: '汉诺塔问题 n 个盘子最少移动步数是', opts: ['n', 'n²', '2ⁿ−1', 'n!'], ans: 2, tip: '递推 T(n)=2T(n-1)+1，解得 T(n)=2ⁿ−1。64 个盘子需 2⁶⁴−1≈1.8×10¹⁹ 步，每秒 1 步要 5800 亿年（"梵天传说"）。' },
        { q: '下列哪种问题最适合用递归求解', opts: ['数组求和', '查找数组最大值', '树的前/中/后序遍历', '冒泡排序'], ans: 2, tip: '树/分治结构天然递归：树遍历、归并排序、快排、汉诺塔、回溯生成排列。简单线性问题用循环更高效（避免栈开销）。' },
        { q: '关于递归与迭代的对比，正确的是', opts: ['递归一定比迭代快', '迭代一定比递归省空间', '尾递归可被编译器优化为循环（但 JavaScript 引擎大多不支持）', '递归不能转换为迭代'], ans: 2, tip: '尾递归（递归是最后一步）理论上可优化为循环（O(1) 栈空间）；C/Scheme 支持，JS 主流引擎不支持（仅 ES6 规范要求）。所有递归都可手动用栈转迭代。' },
    ],
    'dynamic-programming': [
        { q: '动态规划的两个核心特征是', opts: ['递归 + 迭代', '最优子结构 + 重叠子问题', '贪心 + 回溯', '分治 + 剪枝'], ans: 1, tip: 'DP 适用条件：(1)最优子结构（大问题最优解由子问题最优解组合）；(2)重叠子问题（递归会重复计算 → 用表存储避免重复）。否则用分治或贪心。' },
        { q: '0/1 背包问题的状态转移方程是', opts: ['dp[i][j] = dp[i-1][j] + v[i]', 'dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]]+v[i])', 'dp[i][j] = dp[i][j-1] + 1', 'dp[i][j] = dp[i-1][j-1]'], ans: 1, tip: '对每件物品有"取/不取"两种选择：不取 dp[i-1][j]；取 dp[i-1][j-w[i]]+v[i]（j≥w[i]）；取较大者。' },
        { q: '0/1 背包 DP 的时间复杂度是（n=物品数, W=容量）', opts: ['O(n+W)', 'O(n·W)', 'O(n log W)', 'O(2ⁿ)'], ans: 1, tip: 'DP 表 (n+1)×(W+1)，每格 O(1) 计算，总 O(nW)。注意 W 是数值不是输入位数，所以严格说是"伪多项式"时间。' },
        { q: '斐波那契数列 fib(n) 用普通递归 vs DP 复杂度对比', opts: ['递归 O(n)，DP O(n)', '递归 O(2ⁿ)，DP O(n)', '递归 O(n²)，DP O(log n)', '两者相同'], ans: 1, tip: '朴素递归 fib(n)=fib(n-1)+fib(n-2) 重复计算大量子问题，时间 O(2ⁿ)；DP 用数组存中间结果，每个只算一次，O(n)。指数→线性。' },
        { q: '下列问题中，最适合用动态规划求解的是', opts: ['查找数组中的元素', '判断字符串是否回文', '最长公共子序列 LCS', '生成所有排列'], ans: 2, tip: 'LCS 有最优子结构 + 重叠子问题，DP 经典。其他：查找用哈希/二分；回文用双指针；排列用 DFS/回溯。DP 关键是识别状态与转移。' },
    ],

